solution.solution.cpp:
#include <map>
#include <string>
#include <vector>

std::string decorate(const std::string& name, const std::string& returnType, const std::vector<std::string>& parameters)
{
    static const std::map<std::string, std::string> codes{
        { "void", "X" }, { "char", "D" }, { "bool", "_N" }, { "float", "M" },
        { "int", "H" }, { "unsigned int", "I" }, { "long long", "_J" }, { "double", "N" },
    };
    const auto ret{ codes.find(returnType) };
    if (ret == codes.end()) return "";
    std::string out{ "?" + name + "@@YA" + ret->second };
    if (parameters.empty()) return out + "XZ";
    for (const std::string& p : parameters)
    {
        const auto code{ codes.find(p) };
        if (code == codes.end()) return "";
        out += code->second;
    }
    return out + "@Z";
}

unitTests:
TEST("two ints") { CHECK_EQ(decorate("add", "int", { "int", "int" }), std::string("?add@@YAHHH@Z")); }
TEST("no parameters") { CHECK_EQ(decorate("reset", "void", {}), std::string("?reset@@YAXXZ")); CHECK_EQ(decorate("count", "int", {}), std::string("?count@@YAHXZ")); }
TEST("float and bool") { CHECK_EQ(decorate("ratio", "double", { "float", "bool" }), std::string("?ratio@@YANM_N@Z")); }
TEST("the lesson's function") { CHECK_EQ(decorate("stackHeight", "int", { "int", "int" }), std::string("?stackHeight@@YAHHH@Z")); }
TEST("the rest of the table") { CHECK_EQ(decorate("f", "long long", { "char", "unsigned int" }), std::string("?f@@YA_JDI@Z")); }
TEST("unknown types") { CHECK_EQ(decorate("f", "string", {}), std::string("")); CHECK_EQ(decorate("f", "int", { "int", "vector" }), std::string("")); }

